MetalMatrix MetalContext::UploadBF16AsFloat(const void* data,size_t bytes,size_t rows,size_t columns) {
#ifndef GARNET_METAL_DIRECT_FLOAT_WEIGHT_UPLOAD
    throw std::logic_error("Direct FP32 weight upload is disabled");
#else
