    auto native=result.impl_->matrix;
    if(!native||!native.data.contents)throw std::runtime_error("Direct FP32 weight storage unavailable");
    auto destination=static_cast<char*>(native.data.contents)+native.offset;
    auto source=static_cast<const char*>(data);
    const size_t rowBytes=native.rowBytes;
    for(size_t row=0;row<rows;++row) {
        auto outputRow=destination+row*rowBytes;
        auto inputRow=source+2*row*columns;
        for(size_t column=0;column<columns;++column) {
            uint16_t word;std::memcpy(&word,inputRow+2*column,2);
            const uint32_t bits=uint32_t(word)<<16;
